package com.fiap.sast.rules;
import com.fiap.sast.analysis.SecurityFinding; import com.github.javaparser.ast.CompilationUnit; import com.github.javaparser.ast.expr.MethodCallExpr; import org.springframework.stereotype.Component; import java.util.*;
@Component public class RuntimeExecRule implements SecurityRule { public String ruleId(){return "SAST-JAVA-002";} public List<SecurityFinding> analyze(CompilationUnit a,String s,String file){var out=new ArrayList<SecurityFinding>(); a.findAll(MethodCallExpr.class).forEach(m->{if(m.getNameAsString().equals("exec")&&m.getScope().map(x->x.toString().equals("Runtime.getRuntime()")).orElse(false))out.add(RuleSupport.finding(ruleId(),"Uso potencialmente inseguro de Runtime.exec","High","CWE-78","Execução de comando por Runtime.exec.",file,s,m));});return out;} }
